import{c as e,Q as a,j as r,m as o}from"./chunks/framework.dywCjXaF.js";const u=JSON.parse('{"title":"PDF & Export","description":"","frontmatter":{},"headers":[],"relativePath":"export.md","filePath":"export.md"}'),i={name:"export.md"};function n(l,t,s,d,h,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="pdf-export" tabindex="-1">PDF &amp; Export <a class="header-anchor" href="#pdf-export" aria-label="Permalink to &quot;PDF &amp; Export&quot;">​</a></h1><p>Sarva-Varadi has three built-in export formats. No extra tooling needed — everything is in the report itself.</p><nav class="table-of-contents"><ul><li><a href="#pdf-print">PDF Print</a></li><li><a href="#png-chart-download">PNG Chart Download</a></li><li><a href="#csv-export">CSV Export</a></li></ul></nav><hr><h2 id="pdf-print" tabindex="-1">PDF Print <a class="header-anchor" href="#pdf-print" aria-label="Permalink to &quot;PDF Print&quot;">​</a></h2><p>Click the <strong>Print</strong> button (top-right toolbar) to generate a structured PDF.</p><p><strong>What you get:</strong></p><ul><li>A4 landscape orientation</li><li>Page 1: Table of contents with clickable section links</li><li>One page per section: Overview → Failures → Tests → Trends → Timeline → Run History</li><li>Each section has a coloured header (<code>OVERVIEW</code>, <code>FAILURES</code>, etc.) printed at the top of the page</li><li>Page numbers in the footer</li><li>Only print-relevant content shown — filters, banners, buttons are hidden</li><li>Charts rendered as they appear in the browser at print time</li></ul><div class="tip custom-block"><p class="custom-block-title">Viewing a historical run before printing</p><p>If you click <strong>View →</strong> in Run History before printing, the PDF will include a note in the TOC showing which historical run was active (e.g. <code>⏪ Viewing Run #3 · Apr 30, 2026 · 72.7% pass rate</code>). All charts in the PDF reflect that historical run&#39;s data.</p></div><p><strong>Browser tip:</strong> Use Chrome or Edge for the best PDF output. In the print dialog, set destination to &quot;Save as PDF&quot; and enable &quot;Background graphics&quot;.</p><hr><h2 id="png-chart-download" tabindex="-1">PNG Chart Download <a class="header-anchor" href="#png-chart-download" aria-label="Permalink to &quot;PNG Chart Download&quot;">​</a></h2><p>Every chart has a <strong>download</strong> button (↓ icon) in the card header.</p><p>Clicking it saves a PNG of that chart with the Sarva-Varadi logo watermark in the corner.</p><p>Charts available for download:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Charts</th></tr></thead><tbody><tr><td>Overview</td><td>Health Pulse</td></tr><tr><td>Trends</td><td>Pass Rate Trend · Failures &amp; Flakiness · Failures by Severity · Test Count · Run Duration · Top Failing · Top Flaky</td></tr><tr><td>Timeline</td><td>Run Cadence · Execution Gantt</td></tr></tbody></table><hr><h2 id="csv-export" tabindex="-1">CSV Export <a class="header-anchor" href="#csv-export" aria-label="Permalink to &quot;CSV Export&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Location</th><th>What it exports</th></tr></thead><tbody><tr><td>Tests tab toolbar</td><td>All visible tests (name, status, duration, suite, severity, browser)</td></tr><tr><td>Overview → Top Failing</td><td>Failing tests with failure count</td></tr><tr><td>Overview → Top Flaky</td><td>Flaky tests with flaky score</td></tr></tbody></table><p>The CSV opens directly in Excel / Google Sheets and includes column headers.</p>',20)])])}const b=e(i,[["render",n]]);export{u as __pageData,b as default};
